/* Polynomial approximation of atan2(y, x) returning an angle in radians. */ f32 approximateAtan2(f32 x, f32 y) {
    f32 ratioInv;
    f32 ratio;
    f32 angle;
    f32 absX;
    f32 absY;

    if (y == x) {
        angle = 0.7853982f;
        if (y == 0.0f) {
            angle = 0.0f;
        }
    } else {
        absY = y;
        if (y < 0.0f) {
            absY = -y;
        }
        absX = x;
        if (x < 0.0f) {
            absX = -x;
        }
        if (absX < absY) {
            ratio = absX / absY;
            angle = (ratio * 1.06036f) - (ratio * ratio * 0.272123f);
        } else {
            ratioInv = absY / absX;
            angle = 1.5707964f - ((ratioInv * 1.06036f) - (ratioInv * ratioInv * 0.272123f));
        }
    }
    if (y < 0.0f) {
        angle = 3.1415927f - angle;
    }
    if (x < 0.0f) {
        angle = -angle;
    }
    return angle;
}
